{
  "name": "rf_build_cal_block_v3",
  "confidence": "high",
  "docstring": "Builds a 9-byte version-3 RF calibration block by copying and packing selected fields from a source calibration entry into fixed destination offsets.",
  "subsystem": "rf",
  "var_renames": {},
  "struct_hints": [
    {
      "offset": 0,
      "meaning": "destination calibration block version/format byte, set to 3"
    },
    {
      "offset": 1,
      "meaning": "destination reserved byte, set to 0"
    },
    {
      "offset": 2,
      "meaning": "destination byte copied from source entry offset 23"
    },
    {
      "offset": 3,
      "meaning": "destination packed 16-bit flags: (source offset 22 << 2) | (source offset 18 << 1) | (source offset 20 << 6)"
    },
    {
      "offset": 5,
      "meaning": "destination 16-bit field copied from source entry offset 14"
    },
    {
      "offset": 7,
      "meaning": "destination 16-bit field copied from source entry offset 12 and scaled by 16"
    }
  ]
}
